"""Export the JSON Schemas of the v0.1 manifests. The files in ``schema/`` are generated by this.

Usage: ``python -m patchground.spec.schema <out_dir>``

The implementation lives in ``_schema`` so that running this module with ``-m`` does not import it
twice (the package ``__init__`` re-exports ``export_schemas``).
"""

from __future__ import annotations

import argparse
from pathlib import Path

from patchground.spec._schema import (
    GENERATED_COMMENT,
    JSON_SCHEMA_DIALECT,
    SCHEMA_BASE_URL,
    build_schema,
    export_schemas,
    render_schema,
    schema_filename,
)

__all__ = [
    "GENERATED_COMMENT",
    "JSON_SCHEMA_DIALECT",
    "SCHEMA_BASE_URL",
    "build_schema",
    "export_schemas",
    "main",
    "render_schema",
    "schema_filename",
]


def main(argv: list[str] | None = None) -> int:
    """Command-line entry point: write the schema files into ``out_dir``."""
    parser = argparse.ArgumentParser(
        prog="python -m patchground.spec.schema",
        description="Export the challenge.yaml and pack.yaml JSON Schemas.",
    )
    parser.add_argument("out_dir", type=Path, help="directory to write the schema files into")
    args = parser.parse_args(argv)
    for path in export_schemas(args.out_dir):
        print(path)
    return 0


if __name__ == "__main__":
    raise SystemExit(main())
